import{z as o,x as s,o as e,c as l,q as r,j as B,D as a,d as A,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"矩阵树定理","description":"","frontmatter":{"title":"矩阵树定理","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/matrix-tree-theorem.md","filePath":"cs/matrix-tree-theorem.md","lastUpdated":1791413859000}'),p={name:"cs/matrix-tree-theorem.md"};function m(d,E,c,h,D,_){const t=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=r('<h1 id="矩阵树定理" tabindex="-1">矩阵树定理 <a class="header-anchor" href="#矩阵树定理" aria-label="Permalink to &quot;矩阵树定理&quot;">​</a></h1><div class="epigraph"><p>生成树的个数等于拉普拉斯矩阵任意一个主子式的行列式——Kirchhoff 在 1847 年解电路方程时顺手写下的定理。</p><footer>—— G. Kirchhoff, 1847 电路分布论文；矩阵树定理原始出处</footer></div><p><a href="/cs/kitamasa">上一课</a>在序列上用多项式取模压指数；这一课把图钉进矩阵，用一个行列式数清所有生成树。缺口是 <strong>矩阵树定理</strong>：从 \\(O(2^m)\\) 的枚举降到 \\(O(n^3)\\) 的消元。本课写无向图计数与有向树形图变体，不写 BEST 定理的完整推导与谱图理论全貌。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数生成树：暴力枚举边集再判树是指数级；枚举「删 \\(m-n+1\\) 条边」也不可见。代数路径是把「树」这个组合条件翻译成矩阵的秩与行列式。缺口：一个可编程的 \\(O(n^3)\\) 计数器，顺带覆盖带权版本与有向版本。本课不写生成树逐棵枚举、不写复杂度意义下的计数困难类。</p><p><span class="marginnote">术语翻译：Laplacian 拉普拉斯矩阵 = 度矩阵减邻接矩阵；principal minor 主子式，即删去同序号一行一列所得的子方阵；arborescence 树形图，指定根的有向生成树。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三步：构造 \\(L=D-A\\)；删去任意一行与同序号的一列；对余子阵求行列式。模素数下用高斯消元算行列式——每步选主元消列，主元乘进答案，交换两行变号一次。</p>',8)),(e(),B(n,null,{default:a(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AF%BB%E5%85%A5%E5%9B%BE%EF%BC%9A%E6%AF%8F%E6%9D%A1%E8%BE%B9%E7%BB%99%E6%9D%83%E6%88%96%E6%9D%83%201%22%5D%20--%3E%20B%5B%22%E7%B4%AF%E5%8A%A0%E5%BA%A6%E7%9F%A9%E9%98%B5%20D%20%E4%B8%8E%E9%82%BB%E6%8E%A5%E7%9F%A9%E9%98%B5%20A%22%5D%0A%20%20B%20--%3E%20C%5B%22L%20%E7%AD%89%E4%BA%8E%20D%20%E5%87%8F%20A%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%88%A0%E5%8E%BB%E4%BB%BB%E6%84%8F%E4%B8%80%E8%A1%8C%E4%B8%8E%E5%90%8C%E5%BA%8F%E5%8F%B7%E7%9A%84%E4%B8%80%E5%88%97%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%AB%98%E6%96%AF%E6%B6%88%E5%85%83%E6%B1%82%E4%BD%99%E5%AD%90%E9%98%B5%E8%A1%8C%E5%88%97%E5%BC%8F%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%A1%8C%E5%88%97%E5%BC%8F%E5%8D%B3%E7%94%9F%E6%88%90%E6%A0%91%E4%B8%AA%E6%95%B0%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r('<p>带权版：边权 \\(w\\) 解释为「该边独立出现的权重」，行列式输出所有生成树边权乘积之和；想数方案就把权全设为 \\(1\\)。</p><p><span class="marginnote">数字实例：三角形 \\(K_3\\) 的拉普拉斯为三阶矩阵、对角全 \\(2\\)、非对角全 \\(-1\\)；删第三行第三列得 \\(\\begin{pmatrix}2&amp;-1\\\\-1&amp;2\\end{pmatrix}\\)，行列式 \\(=4-1=3\\)——三角形恰有 \\(3\\) 棵生成树，手数一遍正好对上。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么行列式数得清树：连通图的 \\(L\\) 秩恰为 \\(n-1\\)，全一向量躺在零空间里；柯西–比内把主子式的行列式展开成选列方式之和，非树的选法因列重复而抵消为 \\(0\\)，每棵生成树恰好贡献一份——行列式读出的正是树的个数。有向版本只改度数方向：数以 \\(r\\) 为根的内向树形图（各点沿有向边走向 \\(r\\)）用<strong>出度</strong>矩阵，外向树换<strong>入度</strong>，删去的行列固定为根那一行列。</p><p><span class="marginnote">常见误区：不删行列直接算 \\(L\\) 的行列式——全一向量使 \\(L\\) 必奇异，行列式恒为 \\(0\\)，于是得出「没有生成树」的荒谬结论。错在把奇异的整阵扔给了定理，定理要的是主子式。</span></p>',5)),(e(),B(n,null,{default:a(()=>[i(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%7B%22%E6%97%A0%E5%90%91%E8%BF%98%E6%98%AF%E6%9C%89%E5%90%91%22%7D%20--%3E%20U%5B%22%E6%97%A0%E5%90%91%EF%BC%9A%E5%88%A0%E4%BB%BB%E4%B8%80%E8%A1%8C%E5%88%97%E6%B1%82%E4%BD%99%E5%AD%90%E5%BC%8F%22%5D%0A%20%20G%20--%3E%20Di%5B%22%E6%9C%89%E5%90%91%EF%BC%9A%E5%85%88%E5%AE%9A%E6%A0%91%E5%BD%A2%E5%9B%BE%E6%96%B9%E5%90%91%22%5D%0A%20%20Di%20--%3E%20IN%5B%22%E6%95%B0%E5%86%85%E5%90%91%E6%A0%91%EF%BC%9A%E7%94%A8%E5%87%BA%E5%BA%A6%E7%9F%A9%E9%98%B5%22%5D%0A%20%20Di%20--%3E%20OUT%5B%22%E6%95%B0%E5%A4%96%E5%90%91%E6%A0%91%EF%BC%9A%E6%8D%A2%E5%85%A5%E5%BA%A6%E7%9F%A9%E9%98%B5%22%5D%0A%20%20U%20--%3E%20CHK%7B%22%E8%A1%8C%E5%88%97%E5%BC%8F%E4%B8%BA%200%20%E5%90%97%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%98%AF%22%7C%20DISC%5B%22%E5%9B%BE%E4%B8%8D%E8%BF%9E%E9%80%9A%EF%BC%9A%E7%94%9F%E6%88%90%E6%A0%91%E6%95%B0%E4%B8%BA%200%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22%E8%AE%A1%E6%95%B0%E6%88%90%E7%AB%8B%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>计数永远走模素数的整数消元——浮点行列式在 \\(n\\) 上百时就靠不住，错在舍入不可控。与 <a href="/cs/min-cut-applications">min-cut-applications</a> 共享同一张拉普拉斯的脸：那边用它架谱与割的桥，这边只用它的行列式。定理只给个数不给清单——需要逐棵列出生成树时它帮不上忙。删哪一行列都行是性质不是巧合：连通图的所有主子式同值。</p><p><span class="marginnote">直觉类比：把每条边换成一欧电阻，拉普拉斯就是电路的导纳矩阵；删行删列相当于把一个节点接地。接哪个点都不改变能数出的回路结构——「任删一行列」等价于「随便挑一个接地点」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生成树个数 = 拉普拉斯任一主子式的行列式，\\(O(n^3)\\) 可编程。</li><li>度数方向定内外向树形图版本，删去根所在的行列。</li><li>行列式为 \\(0\\) 即不连通，定理顺带当连通性体检。</li><li>出处：G. Kirchhoff, 1847；N. Biggs, <em>Algebraic Graph Theory</em>；Chaiken 与 Kleitman 的矩阵树定理推广, 1978。</li></ul>',5))])}const F=o(p,[["render",m]]);export{f as __pageData,F as default};
